sections.body:
保存为 action-mask.mjs，执行 node action-mask.mjs，无额外依赖。函数接收三项有限 Q 值和严格布尔掩码；同分取前面的动作，全部不合法返回 null。Q 值不必非负，代码也不把它们归一化成概率。

```js
/**
 * @file Demonstrate legal-action selection and a masked Q-learning target.
 * @author liliwei
 * @date 2026-11-20
 * @LastEditors liliwei
 * @LastEditTime 2026-11-20
 */
export const ACTIONS = Object.freeze(['wait', 'strike', 'heal']);

/** Build legality from a teaching snapshot. @param {object} s State. @returns {boolean[]} Mask in ACTIONS order. */
export function legalMask(s) {
  if (!s || !Number.isSafeInteger(s.hp) || s.hp < 0 ||
      !Number.isSafeInteger(s.mp) || s.mp < 0 ||
      typeof s.stunned !== 'boolean' || typeof s.inRange !== 'boolean') {
    throw new TypeError('Invalid state');
  }
  const alive = s.hp > 0;
  return [alive, alive && !s.stunned && s.inRange,
    alive && !s.stunned && s.mp >= 2];
}

/** Select the largest legal Q; ties keep the first ID. @param {number[]} q Finite values. @param {boolean[]} mask Legality. @returns {number|null} Action index or no action. */
export function bestLegal(q, mask) {
  if (!Array.isArray(q) || !Array.isArray(mask) ||
      q.length !== 3 || mask.length !== 3) throw new TypeError('Invalid shape');
  let best = null;
  for (let i = 0; i < 3; i++) {
    if (!Number.isFinite(q[i]) || typeof mask[i] !== 'boolean') {
      throw new TypeError('Invalid value');
    }
    if (mask[i] && (best === null || q[i] > q[best])) best = i;
  }
  return best;
}

/** Form a one-step target, not a complete trainer. @param {number} r Reward. @param {number} gamma Discount in [0,1]. @param {boolean} terminated True task terminal. @param {number[]} nextQ Next-state Q. @param {boolean[]} nextMask Next-state legality. @returns {number} Bellman target. */
export function target(r, gamma, terminated, nextQ, nextMask) {
  if (!Number.isFinite(r) || !Number.isFinite(gamma) || gamma < 0 ||
      gamma > 1 || typeof terminated !== 'boolean') throw new TypeError('Invalid target');
  const next = bestLegal(nextQ, nextMask);
  if (terminated) return r;
  if (next === null) throw new Error('No legal action in nonterminal state');
  const value = r + gamma * nextQ[next];
  if (!Number.isFinite(value)) throw new RangeError('Target overflow');
  return value;
}

const q = [-2, -1, 9]; // Hand-written Q values, not model outputs.
const states = [
  {hp: 5, mp: 0, stunned: false, inRange: true},
  {hp: 5, mp: 2, stunned: true, inRange: true},
  {hp: 0, mp: 2, stunned: false, inRange: true},
  {hp: 5, mp: 2, stunned: false, inRange: true},
];
for (const s of states) {
  const mask = legalMask(s), chosen = bestLegal(q, mask);
  console.log(JSON.stringify({mask, action: chosen === null ? null : ACTIONS[chosen]}));
}
console.log(JSON.stringify({
  maskedTarget: target(2, 0.9, false, q, legalMask(states[0])),
  unmaskedTarget: 2 + 0.9 * Math.max(...q),
  terminalTarget: target(2, 0.9, true, q, legalMask(states[2])),
}));
```

target 只构造一步学习目标 y=r+γ×max合法Q，不更新 Q 表。真正更新还需学习率，例如 Q←Q+α(y−Q)。下一状态真正终止时，目标就是即时奖励 r；非终止状态却没有合法动作，示例抛错，要求修正环境合同，不偷偷抽一个动作。采样时间耗尽的截断不自动等于任务终止，应按任务定义决定是否继续估值。
